import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Users, Link2, CheckCircle, ArrowLeft } from 'lucide-react';
import { motion } from 'framer-motion';
import toast from 'react-hot-toast';
import api from '../utils/api';
import '../styles/join-group.css';

export default function JoinGroup() {
  const { inviteCode } = useParams();
  const navigate = useNavigate();
  const [group, setGroup] = useState(null);
  const [loading, setLoading] = useState(true);
  const [joining, setJoining] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (inviteCode) {
      fetchGroupInfo();
    } else {
      setError('Invalid invite link');
      setLoading(false);
    }
  }, [inviteCode, fetchGroupInfo]);

  const fetchGroupInfo = async () => {
    try {
      const response = await api.get(`/groups/invite/${inviteCode}`);
      setGroup(response.data);
    } catch (error) {
      setError(error.response?.data?.message || 'Failed to load group information');
    } finally {
      setLoading(false);
    }
  };

  const handleJoinGroup = async () => {
    setJoining(true);
    try {
      const response = await api.post(`/groups/join/${inviteCode}`);
      toast.success('Successfully joined the group!');
      navigate(`/group/${response.data._id}`);
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to join group');
    } finally {
      setJoining(false);
    }
  };

  if (loading) {
    return (
      <div className="join-loading">
        <div className="loading-spinner"></div>
        <p>Loading group information...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="join-error">
        <div className="error-container">
          <div className="error-icon">
            <Link2 size={48} />
          </div>
          <h2>Invalid Invite Link</h2>
          <p>{error}</p>
          <button className="back-btn" onClick={() => navigate('/dashboard')}>
            <ArrowLeft size={20} />
            Back to Dashboard
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="join-container">
      <div className="join-header">
        <button className="back-btn" onClick={() => navigate('/dashboard')}>
          <ArrowLeft size={20} />
          Back
        </button>
        <h1>Join Group</h1>
      </div>

      <motion.div
        className="join-card"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        <div className="group-preview">
          <div className="group-icon">
            {group.name.charAt(0).toUpperCase()}
          </div>
          <div className="group-info">
            <h2>{group.name}</h2>
            <p>{group.description || 'No description'}</p>
            <div className="group-meta">
              <span className="category">{group.category}</span>
              <span className="member-count">
                <Users size={16} />
                {group.memberCount || 0} members
              </span>
            </div>
          </div>
        </div>

        <div className="invite-details">
          <div className="invite-code-box">
            <label>Invite Code</label>
            <div className="code-display">
              {inviteCode}
              <button
                className="copy-btn"
                onClick={() => {
                  navigator.clipboard.writeText(inviteCode);
                  toast.success('Invite code copied!');
                }}
              >
                Copy
              </button>
            </div>
          </div>

          <div className="invite-link-box">
            <label>Invite Link</label>
            <div className="link-display">
              <span className="link-text">
                {window.location.origin}/join/{inviteCode}
              </span>
              <button
                className="copy-btn"
                onClick={() => {
                  navigator.clipboard.writeText(`${window.location.origin}/join/${inviteCode}`);
                  toast.success('Invite link copied!');
                }}
              >
                Copy
              </button>
            </div>
          </div>
        </div>

        <div className="join-actions">
          <button className="join-btn" onClick={handleJoinGroup} disabled={joining}>
            {joining ? (
              <>
                <div className="btn-spinner"></div>
                Joining...
              </>
            ) : (
              <>
                <CheckCircle size={20} />
                Join Group
              </>
            )}
          </button>
        </div>

        <div className="join-note">
          <p>
            By joining this group, you'll be able to track expenses and settlements 
            with other members. You can leave the group at any time.
          </p>
        </div>
      </motion.div>
    </div>
  );
}
